const lessons=[{"sentences":[{"speaker":"A","text":"Excuse me because I want to join the local photography club this month.","position":1,"audioStartSeconds":0,"audioEndSeconds":4.708625},{"speaker":"B","text":"Welcome to our community center and I am happy to help you with registration today.","position":2,"audioStartSeconds":4.908625,"audioEndSeconds":10.119791666666666},{"speaker":"A","text":"Although I am a complete beginner, do you offer any special workshops for newcomers?","position":3,"audioStartSeconds":10.319791666666667,"audioEndSeconds":15.539625},{"speaker":"B","text":"We organize a basic camera settings workshop every Tuesday evening for all new members.","position":4,"audioStartSeconds":15.739625,"audioEndSeconds":21.281666666666666},{"speaker":"A","text":"That sounds wonderful because I need to learn how to adjust shutter speed properly.","position":5,"audioStartSeconds":21.481666666666666,"audioEndSeconds":26.35279166666667},{"speaker":"B","text":"Our instructor will demonstrate aperture control and lighting techniques during the first hour.","position":6,"audioStartSeconds":26.552791666666668,"audioEndSeconds":32.32595833333333},{"speaker":"A","text":"Should I bring my own digital camera or can I borrow one from you?","position":7,"audioStartSeconds":32.525958333333335,"audioEndSeconds":36.598125},{"speaker":"B","text":"You should bring your own equipment if possible, but we have spare cameras just in case.","position":8,"audioStartSeconds":36.798125,"audioEndSeconds":42.15895833333333},{"speaker":"A","text":"What about the practical outdoor session that is usually scheduled for the weekend?","position":9,"audioStartSeconds":42.358958333333334,"audioEndSeconds":47.139875},{"speaker":"B","text":"We are visiting the botanical garden this Saturday morning to practice portrait photography outdoors.","position":10,"audioStartSeconds":47.339875,"audioEndSeconds":53.564125},{"speaker":"A","text":"Will there be someone to guide us while we take pictures among the flowers?","position":11,"audioStartSeconds":53.764125,"audioEndSeconds":58.055375},{"speaker":"B","text":"An experienced club mentor will walk with every small group to provide helpful advice.","position":12,"audioStartSeconds":58.255375,"audioEndSeconds":63.616166666666665},{"speaker":"A","text":"Is there any registration fee required before attending the weekend outdoor meeting?","position":13,"audioStartSeconds":63.81616666666667,"audioEndSeconds":68.7775},{"speaker":"B","text":"Participation is completely free for members, but you must sign up online by Friday afternoon.","position":14,"audioStartSeconds":68.9775,"audioEndSeconds":75.06},{"speaker":"A","text":"I will register right now so that I do not miss this great opportunity.","position":15,"audioStartSeconds":75.26,"audioEndSeconds":79.839875},{"speaker":"B","text":"Let me open our website on this tablet to help you complete the form quickly.","position":16,"audioStartSeconds":80.039875,"audioEndSeconds":84.92316666666666}],"questions":[{"prompt":"What is the main purpose of the newcomer's visit?","options":["To buy a new digital camera.","To join the photography club.","To register for a botanical tour."],"answer":"B","evidenceSentence":1,"evidence":"Excuse me because I want to join the local photography club this month.","explanation":"Người nói A đến để hỏi về việc tham gia câu lạc bộ nhiếp ảnh địa phương."},{"prompt":"When does the club hold the basic camera settings workshop?","options":["Every Tuesday evening.","Every Saturday morning.","Every Friday afternoon."],"answer":"A","evidenceSentence":4,"evidence":"We organize a basic camera settings workshop every Tuesday evening for all new members.","explanation":"Buổi hội thảo về cài đặt máy ảnh cơ bản diễn ra vào tối thứ Ba hàng tuần."},{"prompt":"What specific skill does speaker A particularly want to learn?","options":["Portrait photography lighting.","Shutter speed adjustment.","Botanical garden landscaping."],"answer":"B","evidenceSentence":5,"evidence":"That sounds wonderful because I need to learn how to adjust shutter speed properly.","explanation":"Người nói A bày tỏ mong muốn học cách điều chỉnh tốc độ màn trập đúng cách."},{"prompt":"What camera equipment does speaker B suggest bringing?","options":["A borrowed camera from the center.","A spare tablet for registration.","The member's own equipment."],"answer":"C","evidenceSentence":8,"evidence":"You should bring your own equipment if possible, but we have spare cameras just in case.","explanation":"Người nói B khuyên nên mang theo thiết bị riêng của mình nếu có thể."},{"prompt":"Where will the Saturday outdoor practical session take place?","options":["At the community center.","At the botanical garden.","At the local camera store."],"answer":"B","evidenceSentence":10,"evidence":"We are visiting the botanical garden this Saturday morning to practice portrait photography outdoors.","explanation":"Buổi thực hành ngoài trời vào thứ Bảy sẽ diễn ra tại vườn bách thảo."},{"prompt":"What must speaker A do before Friday afternoon?","options":["Pay a workshop fee.","Sign up online.","Borrow a spare camera."],"answer":"B","evidenceSentence":14,"evidence":"Participation is completely free for members, but you must sign up online by Friday afternoon.","explanation":"Người nói A phải đăng ký trực tuyến trước chiều thứ Sáu."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
